import java.util.*;
import java.io.*;

public class VariantOne {
    public static void main(String[] args) throws Exception {
        new VariantOne().execute();
    }

    public void execute() throws Exception {
        Scanner scanner = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        int n = scanner.nextInt();
        long k = scanner.nextLong();

        if (k >= n) {
            writer.println(0);
        } else {
            long[] factorials = new long[n + 1];
            long[] inverses = new long[n + 1];
            final long MOD = 998244353;
            factorials[0] = 1;
            inverses[0] = 1;

            for (int i = 1; i <= n; i++) {
                factorials[i] = (i * factorials[i - 1]) % MOD;
                inverses[i] = modInverse(factorials[i], MOD);
            }

            int r = (int) (n - k);
            long totalWays = 0;

            for (int i = 1; i <= r; i++) {
                long term = factorials[r] * inverses[r - i] % MOD;
                term = term * inverses[i] % MOD;
                term = term * modExp(i, n, MOD) % MOD;
                if ((r - i) % 2 == 1) {
                    term = -term;
                }
                totalWays = (totalWays + term + MOD) % MOD;
            }

            if (k == 0) {
                long result = totalWays * factorials[n] % MOD;
                result = result * inverses[r] % MOD;
                result = result * inverses[n - r] % MOD;
                writer.println(result);
            } else {
                long result = 2 * totalWays % MOD;
                result = result * factorials[n] % MOD;
                result = result * inverses[r] % MOD;
                result = result * inverses[n - r] % MOD;
                writer.println(result);
            }
        }
        writer.flush();
    }

    private long modExp(long base, long exp, long mod) {
        long result = 1;
        long cur = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * cur) % mod;
            }
            cur = (cur * cur) % mod;
            exp >>= 1;
        }
        return result;
    }

    private long modInverse(long a, long m) {
        return modExp(a, m - 2, m);
    }
}
